import{_ as d,o as e,c as a,ak as r}from"./chunks/framework.DKi5cyCJ.js";const b=JSON.parse('{"title":"中断优先级与 FreeRTOS","description":"抢占优先级、子优先级、BASEPRI 分界，以及电机控制的三层协作","frontmatter":{"title":"中断优先级与 FreeRTOS","description":"抢占优先级、子优先级、BASEPRI 分界，以及电机控制的三层协作","date":"2026-10-21T00:00:00.000Z"},"headers":[],"relativePath":"pages/blog/2026-10-21-中断优先级与FreeRTOS.md","filePath":"pages/blog/2026-10-21-中断优先级与FreeRTOS.md"}'),o={name:"pages/blog/2026-10-21-中断优先级与FreeRTOS.md"};function l(s,t,i,c,h,p){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="中断优先级与-freertos" tabindex="-1">中断优先级与 FreeRTOS <a class="header-anchor" href="#中断优先级与-freertos" aria-label="Permalink to &quot;中断优先级与 FreeRTOS&quot;">​</a></h1><blockquote><p>系列目录：<a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">嵌入式驱动面试手册</a>。基础规则见 <a href="/pages/blog/2026-10-20-中断与抢占.html">中断与抢占</a>。</p></blockquote><p>抢占优先级决定能不能打断正在执行的中断。子优先级只在抢占优先级相同时，决定谁先从挂起队列里被选中，永远不能打断正在执行的中断。STM32 HAL 里对应 <code>PreemptPriority</code> 和 <code>SubPriority</code>。</p><table tabindex="0"><thead><tr><th>场景</th><th>结果</th></tr></thead><tbody><tr><td>A 的抢占数值更小</td><td>A 打断 B</td></tr><tr><td>抢占相同，只是子优先级更高</td><td>不能打断，挂起等待</td></tr><tr><td>两者都挂起、CPU 空闲</td><td>先比抢占，再比子优先级，再比 IRQ 号（小号先执行）</td></tr></tbody></table><p>分组是全局的，整个芯片只有一个 <code>PRIGROUP</code>。STM32 实现高 4 位，软件写 0–15。</p><table tabindex="0"><thead><tr><th>HAL 分组</th><th>抢占位</th><th>子优先级位</th></tr></thead><tbody><tr><td>GROUP_0</td><td>0</td><td>4，中断之间不能抢占</td></tr><tr><td>GROUP_1</td><td>1</td><td>3</td></tr><tr><td>GROUP_2</td><td>2</td><td>2</td></tr><tr><td>GROUP_3</td><td>3</td><td>1</td></tr><tr><td>GROUP_4</td><td>4</td><td>0，HAL 默认</td></tr></tbody></table><p>复位后 <code>PRIGROUP = 0</code>。对只实现 4 位的 STM32，效果和 GROUP_4 一样，不是“默认不能抢占”。分组改完后，已经写过的优先级会被重新解释，所以只在初始化时设一次。</p><h2 id="basepri-这条线" tabindex="-1">BASEPRI 这条线 <a class="header-anchor" href="#basepri-这条线" aria-label="Permalink to &quot;BASEPRI 这条线&quot;">​</a></h2><p><code>configMAX_SYSCALL_INTERRUPT_PRIORITY</code> 是 NVIC 数值，不是任务优先级。数值大于等于它的中断，能被 FreeRTOS 临界区挡住，因此允许在 ISR 里调用 <code>FromISR</code> API。数值更小的中断挡不住，禁止调用任何 FreeRTOS API。</p><p>以阈值为 7 为例：</p><table tabindex="0"><thead><tr><th>数值</th><th>临界区能否挡住</th><th>能否调用 API</th></tr></thead><tbody><tr><td>0–6</td><td>不能</td><td>禁止</td></tr><tr><td>7–15</td><td>能</td><td>允许，用 FromISR</td></tr></tbody></table><p>SysTick 和 PendSV 通常放在最低优先级（例如 15），临界区挡得住，上下文切换不会撕开内核链表。NMI 和 HardFault 不吃 BASEPRI，也不能调用 API。</p><p><code>configKERNEL_INTERRUPT_PRIORITY</code> 是 SysTick/PendSV 自己用的优先级，和上面的 syscall 边界不是同一个宏。任务优先级只在没有中断执行时起作用，不能用来判断一个 ISR 会不会打断某个任务。</p><h2 id="电机控制和-rtos" tabindex="-1">电机控制和 RTOS <a class="header-anchor" href="#电机控制和-rtos" aria-label="Permalink to &quot;电机控制和 RTOS&quot;">​</a></h2><div class="blog-flow"><div class="blog-flow-col"><div class="blog-flow-node accent">硬实时<br><small>电流环、换相。优先级高于阈值，不算 API</small></div><div class="blog-flow-down">↓</div><div class="blog-flow-node">协作<br><small>需要通知任务时，优先级落入阈值内，用 FromISR</small></div><div class="blog-flow-down">↓</div><div class="blog-flow-node warn">保护<br><small>过流走比较器和 TIM 刹车，不靠任务</small></div></div></div><p>换相中断如果不调用 API，优先级可以高于阈值，换来更小的抖动。如果它要 <code>xSemaphoreGiveFromISR</code>，优先级必须落在阈值上或更低（数值更大）。不能既高于阈值又调用 API。</p><p>电流环放在 ADC 中断里做运算和写寄存器；速度环放在任务里，通过信号量或一个受保护的参考值交接。过流必须由硬件断开 PWM。</p><p><a href="/pages/blog/2026-10-20-嵌入式驱动面试手册.html">返回目录</a></p>',18)])])}const n=d(o,[["render",l]]);export{b as __pageData,n as default};
